@CrossOrigin
@RestController
@RequestMapping("/ProcedureQuery")
public class ProcedureQueryRestController extends BaseSpringRestController {
	
	public ProcedureQueryRestController( ProcedureService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Procedure using a UUID
     * @param		UUID procedureId
     * @return		Procedure
     */    
    @GetMapping("/load")
    public Procedure load( @RequestParam(required=true) UUID procedureId ) {
    	Procedure entity = null;

    	try {  
    		entity = service.getProcedure( new ProcedureFetchOneSummary( procedureId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Procedure using Id " + procedureId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Procedure business objects
     * @return		Set<Procedure>
     */
    @GetMapping("/")
    public List<Procedure> loadAll() {                
    	List<Procedure> procedureList = null;
        
    	try {
            // load the Procedure
            procedureList = service.getAllProcedure();
            
            if ( procedureList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Procedures" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Procedures ", exc );
        	return null;
        }

        return procedureList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Procedure procedure = null;
    protected ProcedureService service = null;
    private static final Logger LOGGER = Logger.getLogger(ProcedureQueryRestController.class.getName());
    
}
